function main({ histories, memo, turn }) {
  const messages = (Array.isArray(histories) ? histories : [])
    .filter(item => item?.obj === 'Human')
    .map(item => typeof item.value === 'string' ? item.value : Array.isArray(item.value)
      ? item.value.map(part => part?.text?.content ?? '').join('\n') : '');
