  const toText = (html) => decode(html
    .replace(/<!--[^]*?-->/g, ' ')
    .replace(/<(script|style|noscript|svg|header|nav|footer|aside|form|template)\b[^>]*>[^]*?<\/\1\s*>/gi, ' ')
    .replace(/<\/?(?:h[1-6]|p|div|article|section|main|tr|li|br|blockquote)\b[^>]*>/gi, '\n')
    .replace(/<[^>]+>/g, ' '))
    .split(/\r?\n/).map(line => line.replace(/\s+/g, ' ').trim()).filter(Boolean).join('\n');

  const title = toText(/<title\b[^>]*>([^]*?)<\/title\s*>/i.exec(original)?.[1] || '').slice(0, 240);
  const body = /<main\b[^>]*>([^]*?)<\/main\s*>/i.exec(original)?.[1] ||
    /<article\b[^>]*>([^]*?)<\/article\s*>/i.exec(original)?.[1] ||
    /<body\b[^>]*>([^]*?)<\/body\s*>/i.exec(original)?.[1] || original;
  const text = toText(body).slice(0, 16000);
  if (text.length < 30) return { usable: false, prompt: '', sources: memo };
  const url = turn.pageUrl;
  return { usable: true, prompt: JSON.stringify({ title, url, request: turn.input, content: text }),
    sources: mergeSources(memo, [{ key: url, type: '网页正文', title, url, text }]) };
}

